import path from 'node:path';
import { normalizeMimeType } from '../../file-storage/content-type.js';

/**
 * Set of MIME types considered safe to render inline in a browser or Tauri webview.
 *
 * ## Threat Model & Stored XSS Mitigation
 * Artifacts contain user-controlled or agent-generated bytes. When served back to
 * a browser or a Tauri webview with access to local application APIs, returning
 * executable or scriptable formats like `text/html`, `application/xhtml+xml`, or
 * `image/svg+xml` inline allows stored cross-site scripting (XSS).
 *
 * Blanket `attachment` disposition is rejected because the frontend legitimately
 * needs to display documents, markdown, source snippets, structured JSON/CSV, and
 * raster images inline without triggering file download dialogs.
 *
 * Therefore:
 * - Only formats guaranteed not to execute scripts in browser navigation contexts
 *   are permitted inline.
 * - `image/svg+xml` is explicitly excluded from inline rendering because SVGs can
 *   contain `<script>` tags and event handlers.
 * - Any unrecognised or dangerous MIME type is demoted to `application/octet-stream`
 *   and served with `Content-Disposition: attachment`.
 */
export const SAFE_INLINE_MIME_TYPES: ReadonlySet<string> = new Set<string>([
  // Text and structured data
  'text/plain',
  'text/markdown',
  'text/csv',
  'text/css',
  'application/json',
  'application/ld+json',
  'application/yaml',
  'text/yaml',
  'text/x-yaml',
  'application/x-yaml',

  // Safe raster images (SVGs are excluded due to active script injection risks)
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
  'image/avif',
  'image/bmp',
  'image/x-icon',
]);

/**
 * Sanitizes an artifact title or filename for safe inclusion in HTTP headers.
 *
 * Prevents:
 * 1. CRLF injection (`\r`, `\n`) which could inject arbitrary HTTP response headers.
 * 2. Directory traversal sequences (`../`, `..\\`).
 * 3. Header parameter breaking via unescaped quotes (`"`) or backslashes (`\`).
 * 4. Control characters (`\x00-\x1f`, `\x7f`).
 */
export function sanitizeFilename(name: string): string {
  if (!name || typeof name !== 'string') {
    return '';
  }

  // Normalize Windows-style separators to forward slashes before getting basename
  const normalizedSlashes = name.trim().replace(/\\/g, '/');
  const base = path.posix.basename(normalizedSlashes);

  // Remove control characters, null bytes, newlines, carriage returns
  // eslint-disable-next-line no-control-regex
  const stripped = base.replace(/[\x00-\x1f\x7f\r\n]/g, '');

  // Strip quotes and backslashes to prevent header injection or escaping
  const cleaned = stripped.replace(/["\\]/g, '_').trim();

  // If after sanitization the string is empty or solely dots, reject as empty
  if (/^\.*$/.test(cleaned)) {
    return '';
  }

  return cleaned;
}

/**
 * Formats a `Content-Disposition` header according to RFC 6266 and RFC 5987.
 *
 * Includes an ASCII fallback `filename="..."` and an RFC 5987 UTF-8 encoded
 * `filename*=UTF-8''...` parameter when non-ASCII or special characters are present.
 */
export function formatContentDisposition(
  disposition: 'inline' | 'attachment',
  filename?: string,
): string {
  if (!filename) {
    return disposition;
  }

  const sanitized = sanitizeFilename(filename);
  if (!sanitized) {
    return disposition;
  }

  // ASCII fallback: replace any non-printable ASCII characters with underscores
  const asciiFallback = sanitized.replace(/[^\x20-\x7E]/g, '_');

  // Check if RFC 5987 extended parameter is needed (contains non-ASCII or spaces/special chars)
  const isPureAsciiNoSpecial =
    asciiFallback === sanitized && !/[;,\s]/.test(sanitized);

  if (isPureAsciiNoSpecial) {
    return `${disposition}; filename="${asciiFallback}"`;
  }

  const encodedUtf8 = encodeURIComponent(sanitized);
  return `${disposition}; filename="${asciiFallback}"; filename*=UTF-8''${encodedUtf8}`;
}

export interface ContentSecurityPolicyInput {
  readonly mimeType?: string | null;
  readonly isInline: boolean;
  readonly title?: string;
}

export interface ContentSecurityPolicyResult {
  readonly contentType: string;
  readonly disposition: string;
}

/**
 * Resolves the Content-Type and Content-Disposition headers for an artifact.
 *
 * Policy rules:
 * 1. Safe types: If `mimeType` is in {@link SAFE_INLINE_MIME_TYPES}, it is served
 *    with `inline` disposition. Text formats ensure a UTF-8 charset.
 * 2. Unsafe or active types: `text/html`, `image/svg+xml`, scripts, and other
 *    non-allowlisted types are overridden to `application/octet-stream` and forced
 *    to `Content-Disposition: attachment`.
 * 3. Null/missing types: Inline content falls back safely to `text/plain; charset=utf-8`
 *    (inline), while backing files fall back to `application/octet-stream` (attachment)
 *    without sniffing content bytes.
 */
export function resolveContentSecurityPolicy(
  input: ContentSecurityPolicyInput,
): ContentSecurityPolicyResult {
  const { mimeType, isInline, title } = input;

  if (!mimeType || !mimeType.trim()) {
    if (isInline) {
      return {
        contentType: 'text/plain; charset=utf-8',
        disposition: formatContentDisposition('inline', title),
      };
    }
    return {
      contentType: 'application/octet-stream',
      disposition: formatContentDisposition('attachment', title),
    };
  }

  // Extract base MIME type (without parameters like charset)
  const rawType = mimeType.split(';')[0]?.trim() ?? '';
  const normalized = normalizeMimeType(rawType);

  if (SAFE_INLINE_MIME_TYPES.has(normalized)) {
    // Append utf-8 charset for text and json formats
    const isTextual =
      normalized.startsWith('text/') ||
      normalized === 'application/json' ||
      normalized === 'application/ld+json' ||
      normalized === 'application/yaml' ||
      normalized === 'application/x-yaml';

    const finalContentType = isTextual
      ? `${normalized}; charset=utf-8`
      : normalized;

    return {
      contentType: finalContentType,
      disposition: formatContentDisposition('inline', title),
    };
  }

  // Not in safe allow-list: demote to application/octet-stream and force attachment
  return {
    contentType: 'application/octet-stream',
    disposition: formatContentDisposition('attachment', title),
  };
}

export interface ByteRange {
  readonly start: number;
  readonly end: number;
}

/**
 * Parses an HTTP `Range` header (RFC 9110).
 *
 * Returns:
 * - `{ start, end }` for a satisfiable byte range.
 * - `null` if the header is absent, malformed, or uses a unit other than `bytes`.
 * - `'unsatisfiable'` if the range cannot be satisfied for the given resource size.
 */
export function parseRangeHeader(
  rangeHeader: string | undefined,
  totalSize: number,
): ByteRange | null | 'unsatisfiable' {
  if (!rangeHeader || typeof rangeHeader !== 'string') {
    return null;
  }

  const match = /^bytes=(\d*)-(\d*)$/.exec(rangeHeader.trim());
  if (!match) {
    return null;
  }

  const [, startStr, endStr] = match;
  if (!startStr && !endStr) {
    return null;
  }

  let start: number;
  let end: number;

  if (!startStr) {
    // Suffix range: bytes=-N (last N bytes)
    const suffixLength = parseInt(endStr, 10);
    if (suffixLength <= 0 || isNaN(suffixLength)) {
      return 'unsatisfiable';
    }
    start = Math.max(0, totalSize - suffixLength);
    end = totalSize - 1;
  } else if (!endStr) {
    // Prefix range: bytes=N- (from offset N to end of file)
    start = parseInt(startStr, 10);
    end = totalSize - 1;
  } else {
    // Explicit range: bytes=N-M
    start = parseInt(startStr, 10);
    end = parseInt(endStr, 10);
  }

  if (
    isNaN(start) ||
    isNaN(end) ||
    start < 0 ||
    start > end ||
    start >= totalSize ||
    end >= totalSize
  ) {
    return 'unsatisfiable';
  }

  return { start, end };
}
